/* ============ PRUEBAS DEL 2.° TRIMESTRE: unidades nuevas alineadas con los indicadores de logro ============
   Introducción a los métodos de optimización (AE1 y AE2) y Química y ambiente (AE1 a AE3).
   Solo agrega unidades al final de cada ramo (no cambia las existentes). */
(function(){
  const tb = (head, rows) => "<div class='tbl-wrap'><table><thead><tr>" + head.map(h => "<th>" + h + "</th>").join("") + "</tr></thead><tbody>" + rows.map(r => "<tr>" + r.map(c => "<td>" + c + "</td>").join("") + "</tr>").join("") + "</tbody></table></div>";
  const add = (id, units) => { const c = COURSES.find(x => x.id === id); if (!c) return; UZ[id] = UZ[id] || [];
    units.forEach(u => { if (c.u.some(x => x[0] === u.title)) return; c.u.push([u.title, u.res]); UZ[id][c.u.length - 1] = u.z; }); };
  const mc = (q, ops, ok, why) => [q + " " + ops.map((o, i) => "<b>" + "abcd"[i] + ")</b> " + o).join(" "), "<b>Respuesta: " + "abcd"[ok] + ").</b> " + why];

  /* ---------------- INTRODUCCIÓN A LOS MÉTODOS DE OPTIMIZACIÓN ---------------- */
  add("ramo-intro-optimizacion", [
  { title:"5. La ingeniería: desarrollo histórico y conceptos clave (indicador 1.1)",
    res:"<p>La ingeniería industrial nace con la industrialización (siglo XVIII) y se consolida con la administración científica (Taylor), la producción en serie (Ford), el control estadístico (Shewhart, Deming), la investigación de operaciones (1940, Dantzig y el Simplex en 1947) y la producción esbelta (Toyota). Conceptos: sistema, proceso, modelo, eficiencia, eficacia, efectividad, productividad y optimización. El método de la ingeniería va de definir el problema a implementar y controlar la solución.</p>",
    z:{ p:"<p>La prueba parte por aquí: tienes que reconocer quién aportó qué, en qué orden ocurrieron los hitos y qué significa cada concepto. Además, estos conceptos son el vocabulario con que vas a describir cualquier sistema productivo antes de modelarlo.</p>",
      s:"<p>La ingeniería es aplicar ciencia y matemática para resolver problemas reales con recursos limitados. La <b>ingeniería industrial</b> se especializa en diseñar, mejorar y operar <b>sistemas</b> donde se combinan personas, máquinas, materiales, información y energía. Su pregunta de siempre: ¿cómo hacer más y mejor con lo mismo (o con menos)?</p>" +
        tb(["Época", "Hito", "Qué aportó"], [
          ["1760 a 1840", "Primera revolución industrial (máquina de vapor)", "Fábricas, producción mecanizada"],
          ["1776", "Adam Smith, división del trabajo", "Especializar tareas aumenta la productividad"],
          ["1798", "Eli Whitney, piezas intercambiables", "Base de la producción en serie"],
          ["1911", "F. W. Taylor, <i>Principios de la administración científica</i>", "Estudio de tiempos, método estándar"],
          ["1910 a 1920", "Frank y Lillian Gilbreth; Henry Gantt", "Estudio de movimientos; carta Gantt para programar"],
          ["1913", "Henry Ford, línea de montaje móvil", "Producción en masa, menor costo unitario"],
          ["1924 a 1931", "W. Shewhart; luego W. E. Deming", "Control estadístico de procesos; ciclo PHVA y calidad"],
          ["1940 a 1947", "Investigación de operaciones (2.ª Guerra Mundial); G. Dantzig crea el método Simplex", "Optimización matemática para decidir"],
          ["1950 a 1970", "Sistema de Producción Toyota (Ohno, Shingo)", "Justo a tiempo, eliminar desperdicios (lean)"],
          ["Hoy", "Industria 4.0: sensores, datos, automatización, IA", "Decisiones con datos en tiempo real"]]),
      t:[["Sistema", "Conjunto de elementos que interactúan para lograr un objetivo (una planta, un hospital, una red de despacho). Tiene entradas, proceso, salidas, límites y retroalimentación."],
         ["Proceso", "Secuencia de actividades que transforma entradas en salidas con valor para un cliente."],
         ["Modelo", "Representación simplificada de la realidad (física, gráfica o matemática) que permite analizar y decidir sin experimentar con el sistema real."],
         ["Eficiencia", "Lograr el resultado usando pocos recursos: recursos previstos ÷ recursos usados."],
         ["Eficacia", "Lograr el resultado esperado: resultado obtenido ÷ resultado planificado."],
         ["Efectividad", "Ser eficiente y eficaz a la vez (se suele medir como eficiencia × eficacia)."],
         ["Productividad", "Producción ÷ recursos utilizados (unidades por hora-hombre, kg por kWh)."],
         ["Optimización", "Encontrar la mejor decisión (máximo o mínimo de un objetivo) respetando restricciones."],
         ["Restricción", "Límite que la solución debe respetar: capacidad, presupuesto, demanda, normativa."]],
      k:["Definir el problema y el objetivo (qué se quiere mejorar y cómo se medirá).", "Recopilar información y datos del sistema.", "Generar alternativas de solución.", "Construir un modelo (por ejemplo, un modelo de optimización).", "Evaluar las alternativas con el modelo y elegir.", "Implementar la solución.", "Controlar con indicadores y mejorar (volver al paso 1)."],
      e:"<p><b>Eficiencia, eficacia y productividad en una línea de envasado.</b> Se planificó envasar 10.000 botellas en un turno con 80 horas-hombre. Se envasaron 9.000 botellas usando 90 horas-hombre.</p><ul><li>Eficacia = 9.000 ÷ 10.000 = <b>90 %</b> (no se cumplió la meta).</li><li>Eficiencia = 80 ÷ 90 = <b>88,9 %</b> (se usaron más horas de las previstas).</li><li>Efectividad = 0,90 × 0,889 = <b>80 %</b>.</li><li>Productividad real = 9.000 ÷ 90 = <b>100 botellas por hora-hombre</b>; la planificada era 10.000 ÷ 80 = 125. Bajó 20 %.</li></ul>",
      x:["Confundir eficiencia (recursos) con eficacia (resultado). Puedes ser eficaz gastando de más, o eficiente sin cumplir la meta.", "Atribuir el Simplex a Taylor o la carta Gantt a Ford: memoriza la tabla de hitos con su aporte.", "Decir que un modelo es «la realidad»: siempre es una simplificación con supuestos."],
      q:[mc("¿Quién desarrolló el método Simplex?", ["Frederick Taylor", "George Dantzig", "Henry Gantt", "Taiichi Ohno"], 1, "Dantzig lo publicó en 1947, en el origen de la investigación de operaciones."),
         mc("Una empresa cumplió 100 % de su meta de producción, pero gastó 30 % más de materiales de lo previsto. Fue:", ["Eficiente y eficaz", "Eficaz pero no eficiente", "Eficiente pero no eficaz", "Ni eficiente ni eficaz"], 1, "Cumplió el resultado (eficaz) usando más recursos (no eficiente)."),
         mc("La administración científica, basada en el estudio de tiempos y métodos estándar, se asocia a:", ["Deming", "Taylor", "Shewhart", "Smith"], 1, "Taylor, 1911."),
         mc("¿Cuál NO es un elemento de un sistema?", ["Entradas", "Proceso", "Retroalimentación", "Opinión del analista"], 3, "Un sistema tiene entradas, proceso, salidas, límites y retroalimentación.")] } },

  { title:"6. Ideas de negocio con herramientas de ingeniería (indicador 1.2)",
    res:"<p>Una idea de negocio parte de un problema o necesidad real. Herramientas para distinguirla y evaluarla: análisis del entorno (PESTEL), FODA, lienzo de modelo de negocios (Canvas, 9 bloques), propuesta de valor, pensamiento de diseño, Lean Startup (producto mínimo viable y ciclo construir, medir, aprender) y evaluación económica básica (punto de equilibrio, margen de contribución).</p>",
    z:{ p:"<p>El indicador pide <b>distinguir</b> ideas de negocio usando herramientas de ingeniería adecuadas a la situación actual. En la prueba te pueden dar una idea y preguntar qué herramienta corresponde, en qué bloque del Canvas va un dato o si el negocio cubre sus costos.</p>",
      s:"<p>Una idea no es un negocio hasta que responde tres preguntas: ¿a quién le resuelvo qué problema?, ¿por qué me elegirían a mí?, ¿gano dinero haciéndolo? Las herramientas ordenan esas respuestas.</p>" +
        tb(["Herramienta", "Para qué sirve", "Pregunta que responde"], [
          ["PESTEL", "Analizar el entorno: Político, Económico, Social, Tecnológico, Ecológico (ambiental) y Legal", "¿Qué tendencias externas favorecen o amenazan la idea?"],
          ["FODA", "Fortalezas y Debilidades (internas); Oportunidades y Amenazas (externas)", "¿Con qué cuento y qué me rodea?"],
          ["Lienzo de modelo de negocios (Canvas)", "Describir el negocio en 9 bloques en una sola hoja", "¿Cómo crea, entrega y captura valor?"],
          ["Mapa de propuesta de valor", "Calzar los dolores y alegrías del cliente con lo que ofreces", "¿Por qué me comprarían?"],
          ["Pensamiento de diseño (design thinking)", "Empatizar, definir, idear, prototipar, testear", "¿Entendí bien el problema del usuario?"],
          ["Lean Startup", "Probar barato con un producto mínimo viable (PMV) y aprender de datos", "¿El cliente realmente lo quiere?"],
          ["Punto de equilibrio", "Cantidad mínima a vender para no perder", "¿Es viable económicamente?"]]) +
        "<p><b>Los 9 bloques del Canvas</b> (Osterwalder): segmentos de clientes, propuesta de valor, canales, relación con clientes, fuentes de ingreso (lado derecho, el mercado); recursos clave, actividades clave, socios clave y estructura de costos (lado izquierdo, la operación). El ingeniero industrial aporta sobre todo en el lado izquierdo: procesos, capacidad, costos.</p>" +
        "<p><b>Situación actual (oportunidades típicas):</b> digitalización y comercio electrónico, economía circular y Ley REP, eficiencia energética y energías renovables, escasez hídrica, envejecimiento de la población, automatización e inteligencia artificial, logística de última milla.</p>",
      t:[["PMV", "Producto mínimo viable: la versión más simple que permite probar la idea con clientes reales."], ["Margen de contribución", "Precio − costo variable unitario: lo que cada unidad aporta para cubrir costos fijos."], ["Costo fijo", "No cambia con la cantidad producida (arriendo, sueldos fijos)."], ["Costo variable", "Cambia con cada unidad (materia prima, envase)."], ["Punto de equilibrio", "Q* = Costos fijos ÷ (Precio − Costo variable unitario)."]],
      k:["Identifica el problema y a quién afecta (segmento).", "Revisa el entorno con PESTEL y resume con FODA.", "Arma el Canvas en una hoja.", "Calcula el punto de equilibrio con costos estimados.", "Diseña un PMV y define qué medir para validar.", "Decide: seguir, ajustar (pivotar) o descartar."],
      e:"<p><b>Idea: reparto de cajas de verduras a domicilio en Temuco.</b></p><ul><li><b>Problema:</b> familias sin tiempo para ir a la feria. <b>Segmento:</b> hogares de 25 a 45 años con trabajo presencial.</li><li><b>FODA:</b> F = contacto directo con agricultores; D = sin flota propia; O = crecimiento de compras por internet; A = supermercados con despacho.</li><li><b>Economía:</b> precio de la caja $ 15.000; costo variable (verduras, caja, reparto) $ 9.000; costos fijos $ 1.800.000 al mes (bodega, sueldo, aplicación).</li><li>Margen de contribución = 15.000 − 9.000 = $ 6.000 por caja.</li><li>Punto de equilibrio = 1.800.000 ÷ 6.000 = <b>300 cajas al mes</b> (unas 75 por semana).</li><li><b>PMV:</b> antes de arrendar bodega, vender 30 cajas por semana con un formulario y reparto propio durante un mes, y medir recompra.</li></ul>",
      x:["Poner las amenazas como debilidades: las debilidades son internas, las amenazas externas.", "Llenar el Canvas sin validar con clientes reales.", "Calcular el punto de equilibrio dividiendo por el precio en vez de por el margen de contribución."],
      q:[mc("En el Canvas, «arriendo de bodega y sueldos» corresponde al bloque:", ["Fuentes de ingreso", "Estructura de costos", "Socios clave", "Canales"], 1, "Son costos de operar el negocio."),
         mc("La llegada de una gran cadena con despacho gratis es, en un FODA:", ["Fortaleza", "Debilidad", "Oportunidad", "Amenaza"], 3, "Es externa y negativa."),
         mc("Precio $ 2.000, costo variable $ 1.200, costos fijos $ 400.000. El punto de equilibrio es:", ["200 unidades", "333 unidades", "500 unidades", "800 unidades"], 2, "400.000 ÷ (2.000 − 1.200) = 500."),
         mc("¿Qué herramienta prueba la idea con clientes reales al menor costo posible?", ["PESTEL", "Producto mínimo viable", "Carta Gantt", "Diagrama de Pareto"], 1, "El PMV es la base de Lean Startup.")] } },

  { title:"7. Objetivos SMART e indicadores (indicador 1.3)",
    res:"<p>Un objetivo SMART es eSpecífico, Medible, Alcanzable, Relevante y con plazo (Tiempo). Cada objetivo se controla con un indicador (KPI) definido en una ficha: nombre, fórmula, unidad, frecuencia, meta, responsable y fuente de datos. En optimización, el objetivo SMART se traduce en la función objetivo y las metas en restricciones.</p>",
    z:{ p:"<p>Sin un objetivo claro no hay qué optimizar: «mejorar la producción» no se puede medir ni modelar. «Aumentar la producción de 900 a 1.000 unidades por turno antes del 30 de junio» sí.</p>",
      s:tb(["Letra", "Significa", "Pregunta de control"], [
          ["S", "eSpecífico (Specific)", "¿Qué exactamente, dónde, en qué proceso?"],
          ["M", "Medible (Measurable)", "¿Con qué número sabré si lo logré?"],
          ["A", "Alcanzable (Achievable)", "¿Es posible con los recursos que tengo?"],
          ["R", "Relevante (Relevant)", "¿Aporta a la estrategia de la empresa?"],
          ["T", "Con plazo (Time-bound)", "¿Para cuándo?"]]) +
        "<p><b>Indicador (KPI):</b> número que mide el avance hacia un objetivo. Tipos frecuentes: de <b>eficacia</b> (cumplimiento de la meta), de <b>eficiencia</b> (uso de recursos), de <b>calidad</b> (defectos, reclamos), de <b>productividad</b> (salida ÷ recurso) y de <b>servicio</b> (entregas a tiempo).</p>" +
        tb(["Campo de la ficha", "Ejemplo"], [["Nombre", "Entregas a tiempo"], ["Fórmula", "Pedidos entregados en fecha ÷ pedidos totales × 100"], ["Unidad", "%"], ["Frecuencia", "Semanal"], ["Meta", "≥ 95 %"], ["Responsable", "Jefe de despacho"], ["Fuente", "Sistema de pedidos (ERP)"]]),
      t:[["KPI", "Indicador clave de desempeño (Key Performance Indicator)."], ["Línea base", "Valor actual del indicador antes de mejorar; sin ella no sabes cuánto avanzaste."], ["Meta", "Valor que se quiere alcanzar en el plazo."], ["Semáforo", "Rangos que muestran si el indicador está bien (verde), en riesgo (amarillo) o mal (rojo)."]],
      k:["Parte del problema y su línea base (dato actual).", "Escribe el objetivo con verbo + qué + cuánto + dónde + cuándo.", "Revisa las 5 letras una por una.", "Define el indicador con su ficha completa.", "Fija la meta y la frecuencia de medición.", "Si lo vas a optimizar, traduce: lo que se maximiza o minimiza es la función objetivo; las metas mínimas son restricciones."],
      e:"<p><b>Mal:</b> «Reducir las mermas de la panadería». <b>Bien (SMART):</b> «Reducir la merma de pan amasado de 8 % a 5 % del total producido en la sucursal Ñuñoa, antes del 31 de marzo, ajustando la producción diaria a la demanda». Indicador: merma (%) = kg no vendidos ÷ kg producidos × 100, medición diaria, responsable el jefe de producción.</p><p><b>Seguimiento:</b> en una semana se producen 1.250 kg y quedan 75 kg sin vender: merma = 75 ÷ 1.250 × 100 = <b>6 %</b>. Avance = (8 − 6) ÷ (8 − 5) = 67 % del camino hacia la meta: semáforo amarillo.</p><p><b>Conexión con optimización:</b> «máx Z = utilidad» sujeto a «producción de cada pan ≤ demanda pronosticada» es el modelo que ayuda a cumplir ese objetivo.</p>",
      x:["Objetivos sin número ni plazo («mejorar la calidad»).", "Indicadores sin línea base.", "Metas imposibles (no alcanzables) que desmotivan.", "Confundir el objetivo (lo que quiero) con la acción (cómo lo haré)."],
      q:[mc("«Aumentar las ventas» no es SMART principalmente porque:", ["No es relevante", "No es medible ni tiene plazo", "No es alcanzable", "Es demasiado específico"], 1, "No dice cuánto ni para cuándo."),
         mc("¿Cuál es un objetivo SMART?", ["Ser la mejor empresa del rubro", "Bajar los reclamos", "Reducir los reclamos por despacho de 40 a 20 al mes antes de diciembre", "Mejorar el clima laboral pronto"], 2, "Es específico, medible, alcanzable, relevante y con plazo."),
         mc("En una ficha de indicador, «pedidos entregados en fecha ÷ pedidos totales × 100» es:", ["La meta", "La fórmula", "La fuente", "La frecuencia"], 1, "Es la forma de calcularlo."),
         mc("La letra A de SMART se refiere a que el objetivo sea:", ["Anual", "Alcanzable", "Automático", "Auditado"], 1, "Achievable: posible con los recursos disponibles.")] } },

  { title:"8. Elementos y tipos de modelos de optimización en las organizaciones (indicadores 2.1, 2.2 y 2.3)",
    res:"<p>Elementos: parámetros (datos), variables de decisión, función objetivo, restricciones y no negatividad. Supuestos de la programación lineal: proporcionalidad, aditividad, divisibilidad y certeza. Modelos típicos: mezcla de productos, dieta o mezcla de insumos, transporte, asignación, programación de turnos, inversión o presupuesto (variables binarias) y planificación de producción con inventario.</p>",
    z:{ p:"<p>La prueba pide reconocer los elementos de un modelo y plantear (no necesariamente resolver) modelos para distintas situaciones. Casi todos los problemas de empresa caen en uno de estos tipos: si reconoces el tipo, ya tienes la forma del modelo.</p>",
      s:"<p><b>Supuestos de la programación lineal</b> (si alguno no se cumple, el modelo no es lineal o necesita variables enteras):</p><ul><li><b>Proporcionalidad:</b> el aporte de cada variable es proporcional a su valor (el doble de mesas da el doble de utilidad).</li><li><b>Aditividad:</b> el total es la suma de los aportes de cada variable.</li><li><b>Divisibilidad:</b> las variables pueden tomar valores fraccionarios.</li><li><b>Certeza:</b> los parámetros se conocen con seguridad.</li></ul>" +
        tb(["Tipo de modelo", "Variable típica", "Objetivo", "Restricciones típicas"], [
          ["Mezcla de productos", "x<sub>j</sub> = unidades del producto j", "máx utilidad", "horas de máquina, materia prima, demanda"],
          ["Dieta o mezcla de insumos", "x<sub>j</sub> = kg del insumo j", "mín costo", "nutrientes o calidad mínima, total a producir"],
          ["Transporte", "x<sub>ij</sub> = unidades de origen i a destino j", "mín costo de flete", "oferta de cada origen, demanda de cada destino"],
          ["Asignación", "x<sub>ij</sub> = 1 si la persona i hace la tarea j (si no, 0)", "mín tiempo o costo", "cada persona una tarea, cada tarea una persona"],
          ["Turnos de personal", "x<sub>t</sub> = personas que empiezan en el turno t", "mín personas o costo", "personas presentes ≥ requeridas en cada bloque"],
          ["Inversión o presupuesto", "y<sub>j</sub> = 1 si se hace el proyecto j", "máx VAN", "presupuesto disponible"],
          ["Producción con inventario", "P<sub>t</sub> = producción, I<sub>t</sub> = inventario del mes t", "mín costo de producir y guardar", "I<sub>t−1</sub> + P<sub>t</sub> − D<sub>t</sub> = I<sub>t</sub>; capacidad"]]),
      t:[["Parámetro", "Dato conocido que no decides (costo, capacidad, demanda)."], ["Variable binaria", "Solo puede valer 0 o 1 (sí o no). Hace que el modelo sea de programación entera."], ["Programación entera", "PL en que algunas variables deben ser enteras (camiones, personas)."], ["Balance de inventario", "Inventario inicial + producción − demanda = inventario final."]],
      k:["Identifica el tipo de problema con la tabla.", "Lista los parámetros (datos) con su unidad.", "Define las variables (con índices si hay orígenes, destinos o períodos).", "Escribe la función objetivo como suma de coeficiente × variable.", "Escribe una restricción por cada recurso, oferta, demanda o exigencia.", "Agrega no negatividad (y si corresponde, enteras o binarias).", "Revisa que se cumplan los supuestos de la PL."],
      e:"<p><b>Transporte.</b> Una empresa de alimentos tiene plantas en Rancagua (oferta 300 t) y Talca (200 t), y debe abastecer Santiago (250 t), Concepción (150 t) y Valparaíso (100 t). Costos de flete por tonelada:</p>" +
        tb(["", "Santiago", "Concepción", "Valparaíso"], [["Rancagua", "$ 8.000", "$ 20.000", "$ 15.000"], ["Talca", "$ 18.000", "$ 12.000", "$ 25.000"]]) +
        "<p>Variables: x<sub>ij</sub> = toneladas desde la planta i al destino j (i = R, T; j = S, C, V).</p><p>mín Z = 8.000x<sub>RS</sub> + 20.000x<sub>RC</sub> + 15.000x<sub>RV</sub> + 18.000x<sub>TS</sub> + 12.000x<sub>TC</sub> + 25.000x<sub>TV</sub></p><p>Oferta: x<sub>RS</sub> + x<sub>RC</sub> + x<sub>RV</sub> ≤ 300; x<sub>TS</sub> + x<sub>TC</sub> + x<sub>TV</sub> ≤ 200.</p><p>Demanda: x<sub>RS</sub> + x<sub>TS</sub> = 250; x<sub>RC</sub> + x<sub>TC</sub> = 150; x<sub>RV</sub> + x<sub>TV</sub> = 100. Todas x<sub>ij</sub> ≥ 0.</p><p>Oferta total 500 = demanda total 500 (problema balanceado). Una solución lógica: Rancagua envía 250 a Santiago y 50 a Valparaíso; Talca envía 150 a Concepción y 50 a Valparaíso. Costo = 250 × 8.000 + 50 × 15.000 + 150 × 12.000 + 50 × 25.000 = <b>$ 5.800.000</b>, que es el mínimo (hay otra solución con el mismo costo: Rancagua 200 a Santiago y 100 a Valparaíso; Talca 50 a Santiago y 150 a Concepción). Verifícalo con la calculadora de transporte del programa.</p>" +
        "<p><b>Turnos.</b> Un call center necesita al menos 6 personas de 8 a 12 h, 10 de 12 a 16 h y 7 de 16 a 20 h. Cada persona trabaja 8 horas seguidas: turno A (8 a 16 h) o turno B (12 a 20 h). Variables: x<sub>A</sub>, x<sub>B</sub> = personas por turno. mín Z = x<sub>A</sub> + x<sub>B</sub> s.a. x<sub>A</sub> ≥ 6; x<sub>A</sub> + x<sub>B</sub> ≥ 10; x<sub>B</sub> ≥ 7; enteras ≥ 0. Óptimo: x<sub>A</sub> = 6, x<sub>B</sub> = 7, 13 personas (de 12 a 16 h hay 13, más que las 10 pedidas).</p>",
      x:["Usar una sola variable cuando hay orígenes y destinos: en transporte hacen falta dos índices (x<sub>ij</sub>).", "Poner ≤ en la demanda cuando el enunciado exige cumplirla completa (debe ser = o ≥).", "Olvidar que personas y camiones son enteros.", "Confundir parámetro (dato) con variable (decisión)."],
      q:[mc("En un modelo de PL, «la capacidad del horno es 16 horas» es:", ["Una variable de decisión", "Un parámetro usado en una restricción", "La función objetivo", "Una variable binaria"], 1, "Es un dato fijo que limita la solución."),
         mc("Con 3 plantas y 4 bodegas, un modelo de transporte tiene:", ["7 variables", "12 variables", "3 variables", "4 variables"], 1, "Una por cada ruta: 3 × 4 = 12."),
         mc("¿Qué supuesto de la PL se viola si producir 1,5 camiones no tiene sentido?", ["Proporcionalidad", "Aditividad", "Divisibilidad", "Certeza"], 2, "Las variables deben poder ser fraccionarias; si no, es programación entera."),
         mc("Para decidir qué proyectos financiar con un presupuesto fijo se usan variables:", ["Continuas", "Binarias", "Negativas", "De holgura"], 1, "1 si se hace el proyecto, 0 si no."),
         mc("En el problema de asignación, cada restricción dice que:", ["La suma de costos es mínima", "Cada persona hace exactamente una tarea y cada tarea la hace una persona", "La oferta supera a la demanda", "Las variables son negativas"], 1, "Por eso todas las restricciones son «= 1».")] } },

  { title:"9. Repaso para la prueba: mapa de indicadores y preguntas tipo",
    res:"<p>Mapa de indicadores de logro con la unidad donde se estudia cada uno, y preguntas de selección con su pauta.</p>",
    z:{ s:tb(["Indicador", "Qué te piden", "Dónde estudiarlo"], [
          ["1.1", "Reconocer elementos del desarrollo de la ingeniería y conceptos", "Unidad 1"],
          ["1.2", "Distinguir ideas de negocio con herramientas de ingeniería", "Unidad 2"],
          ["1.3", "Objetivos SMART e indicadores", "Unidad 3"],
          ["2.1", "Elementos de un modelo de programación lineal", "Unidades 4 y 7"],
          ["2.2", "Representar modelos lineales de sistemas productivos y de servicios", "Unidades 4, 5, 6 y 7"],
          ["2.3", "Representar modelos para distintos problemas de las organizaciones", "Unidades 7 y 8"]]) +
        "<p><b>Cómo responder una prueba de selección de modelación:</b> (1) lee el enunciado y marca qué se decide, qué se busca y qué limita; (2) antes de mirar las alternativas, escribe tú la variable, el objetivo y una restricción; (3) descarta alternativas con unidades que no calzan o con el signo de desigualdad equivocado; (4) si piden el óptimo de dos variables, evalúa Z en todos los vértices.</p>",
      q:[mc("Una fábrica gana $ 40 por unidad de A y $ 30 por unidad de B. A usa 2 h de máquina y B usa 1 h; hay 100 h. La función objetivo es:", ["mín Z = 2x<sub>A</sub> + x<sub>B</sub>", "máx Z = 40x<sub>A</sub> + 30x<sub>B</sub>", "máx Z = 2x<sub>A</sub> + x<sub>B</sub>", "máx Z = 40 + 30"], 1, "Se maximiza la utilidad: ganancia unitaria × cantidad."),
         mc("En el mismo problema, la restricción de máquina es:", ["2x<sub>A</sub> + x<sub>B</sub> ≥ 100", "40x<sub>A</sub> + 30x<sub>B</sub> ≤ 100", "2x<sub>A</sub> + x<sub>B</sub> ≤ 100", "x<sub>A</sub> + x<sub>B</sub> ≤ 100"], 2, "Horas usadas ≤ horas disponibles."),
         mc("Vértices de la región factible: (0, 0), (50, 0), (0, 80) y (20, 60). Si máx Z = 40x<sub>1</sub> + 30x<sub>2</sub>, el óptimo es:", ["(50, 0) con Z = 2.000", "(0, 80) con Z = 2.400", "(20, 60) con Z = 2.600", "(0, 0)"], 2, "Z(50,0) = 2.000; Z(0,80) = 2.400; Z(20,60) = 800 + 1.800 = 2.600."),
         mc("Si al graficar ningún punto cumple todas las restricciones, el problema es:", ["No acotado", "Infactible", "Degenerado", "Con óptimos múltiples"], 1, "No existe región factible."),
         mc("La restricción «x<sub>1</sub>, x<sub>2</sub> ≥ 0» se llama:", ["Holgura", "No negatividad", "Restricción activa", "Función objetivo"], 1, "No se produce en cantidades negativas."),
         mc("Si la recta de la función objetivo es paralela a una restricción activa en el óptimo, hay:", ["Infactibilidad", "Óptimos múltiples", "Solución no acotada", "Un error de modelación"], 1, "Todos los puntos de ese borde dan el mismo Z.")] } }
  ]);

  /* ---------------- QUÍMICA Y AMBIENTE ---------------- */
  add("ramo-quimica-ambiente", [
  { title:"5. Balanceo de ecuaciones: masa y carga (indicador 1.1)",
    res:"<p>Una ecuación balanceada tiene la misma cantidad de átomos de cada elemento y la misma carga total a ambos lados. Métodos: tanteo (reacciones sencillas), algebraico y método del ion-electrón para reacciones redox (en medio ácido o básico).</p>",
    z:{ p:"<p>Todo cálculo de la prueba (masas, gases, energía, CO₂) parte de una ecuación balanceada. Si el balance está mal, todo lo que sigue está mal.</p>",
      s:"<p><b>Reactivos</b> a la izquierda, <b>productos</b> a la derecha. Solo puedes cambiar los <b>coeficientes</b> (los números grandes delante), nunca los subíndices: cambiar H₂O por H₂O₂ cambia la sustancia.</p><p><b>Método por tanteo (orden recomendado):</b> primero los metales, luego los no metales distintos de H y O, después el H y al final el O. Si queda un coeficiente fraccionario, multiplica todo por el denominador.</p><p><b>Reacciones redox:</b> un elemento se oxida (pierde electrones, su número de oxidación sube) y otro se reduce (gana electrones, baja). Se balancean por separado las dos semirreacciones y se igualan los electrones, así se conserva también la <b>carga</b>.</p>",
      t:[["Coeficiente estequiométrico", "Número delante de la fórmula; indica cuántas moléculas o moles participan."], ["Subíndice", "Número pequeño dentro de la fórmula; no se toca al balancear."], ["Oxidación", "Pérdida de electrones (aumenta el número de oxidación)."], ["Reducción", "Ganancia de electrones (disminuye el número de oxidación)."], ["Agente oxidante", "La especie que se reduce (provoca la oxidación de otra)."], ["Agente reductor", "La especie que se oxida."]],
      k:["Escribe reactivos y productos con fórmulas correctas.", "Cuenta átomos de cada elemento a cada lado (haz una tabla).", "Ajusta coeficientes: metales, no metales, H y O al final.", "En redox: separa semirreacciones, balancea átomos, el O con H₂O, el H con H⁺ y la carga con electrones (e⁻).", "Multiplica las semirreacciones para que los electrones sean iguales y súmalas.", "Comprueba átomos y carga total a ambos lados."],
      e:"<p><b>1. Combustión del propano (gas licuado):</b> C₃H₈ + O₂ → CO₂ + H₂O.</p><ul><li>C: 3 a la izquierda → 3 CO₂.</li><li>H: 8 → 4 H₂O.</li><li>O a la derecha: 3 × 2 + 4 × 1 = 10 → 5 O₂.</li><li><b>C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O</b>. Comprobación: C 3 = 3; H 8 = 8; O 10 = 10.</li></ul><p><b>2. Alto horno:</b> Fe₂O₃ + CO → Fe + CO₂ → <b>Fe₂O₃ + 3 CO → 2 Fe + 3 CO₂</b> (Fe 2 = 2; C 3 = 3; O 3 + 3 = 6 = 6).</p><p><b>3. Redox con carga (medio ácido):</b> MnO₄⁻ + Fe²⁺ → Mn²⁺ + Fe³⁺.</p><ul><li>Oxidación: Fe²⁺ → Fe³⁺ + 1 e⁻.</li><li>Reducción: MnO₄⁻ + 8 H⁺ + 5 e⁻ → Mn²⁺ + 4 H₂O (4 O se van como 4 H₂O; 8 H⁺ dan esos H; la carga: −1 + 8 − 5 = +2 a la izquierda, +2 a la derecha).</li><li>Igualar electrones: la oxidación × 5.</li><li><b>MnO₄⁻ + 5 Fe²⁺ + 8 H⁺ → Mn²⁺ + 5 Fe³⁺ + 4 H₂O</b>. Carga: −1 + 10 + 8 = +17 a la izquierda; +2 + 15 = +17 a la derecha.</li></ul>",
      x:["Cambiar subíndices para cuadrar átomos.", "Balancear átomos y olvidar la carga en las reacciones iónicas.", "Dejar coeficientes fraccionarios en la respuesta final o no simplificarlos (2, 4, 6 → 1, 2, 3).", "Confundir oxidante con la especie que se oxida."],
      q:[mc("Al balancear CH₄ + O₂ → CO₂ + H₂O, el coeficiente del O₂ es:", ["1", "2", "3", "4"], 1, "CH₄ + 2 O₂ → CO₂ + 2 H₂O: 4 O a cada lado."),
         mc("En 2 H₂ + O₂ → 2 H₂O, ¿qué se conserva?", ["El número de moléculas", "El número de átomos de cada elemento", "El volumen", "El número de moles"], 1, "Hay 3 moléculas a la izquierda y 2 a la derecha, pero 4 H y 2 O a ambos lados."),
         mc("En Zn + Cu²⁺ → Zn²⁺ + Cu, la especie que se oxida es:", ["Cu²⁺", "Zn", "Zn²⁺", "Cu"], 1, "Zn pasa de 0 a +2: pierde electrones."),
         mc("¿Cuál ecuación está balanceada en masa y carga?", ["Fe³⁺ + Cu → Fe²⁺ + Cu²⁺", "2 Fe³⁺ + Cu → 2 Fe²⁺ + Cu²⁺", "Fe³⁺ + 2 Cu → Fe²⁺ + 2 Cu²⁺", "2 Fe³⁺ + 2 Cu → 2 Fe²⁺ + Cu²⁺"], 1, "Carga: +6 = +4 + 2; átomos: 2 Fe y 1 Cu a cada lado.")] } },

  { title:"6. Pesos atómicos y moleculares (indicador 1.2)",
    res:"<p>La escala de masas atómicas usa como referencia el carbono 12 (1 uma = 1/12 de la masa de un átomo de ¹²C). La masa atómica de la tabla es el promedio ponderado de los isótopos. La masa molecular es la suma de las masas atómicas de la fórmula; en g/mol es la masa molar.</p>",
    z:{ p:"<p>La masa molar es el puente entre lo que pesas en la planta (kilos) y lo que cuenta la ecuación (moles). Sin ella no hay estequiometría.</p>",
      s:"<p>Los átomos son demasiado livianos para pesarlos en gramos, así que se usa una escala relativa: la <b>unidad de masa atómica (uma o u)</b>. El ¹²C pesa exactamente 12 u. Un mol de cualquier sustancia (6,022 × 10²³ partículas) pesa en gramos lo mismo que su masa en u.</p><p><b>Masa atómica promedio:</b> la mayoría de los elementos tiene isótopos (mismo número de protones, distinto número de neutrones). La tabla periódica muestra el promedio ponderado por la abundancia de cada isótopo.</p>" +
        tb(["Elemento", "Masa atómica (u)", "Elemento", "Masa atómica (u)"], [["H", "1,008", "Na", "22,99"], ["C", "12,01", "S", "32,06"], ["N", "14,01", "Cl", "35,45"], ["O", "16,00", "Ca", "40,08"], ["Fe", "55,85", "Cu", "63,55"]]),
      t:[["uma (u)", "1/12 de la masa de un átomo de carbono 12."], ["Isótopo", "Átomo del mismo elemento con distinto número de neutrones."], ["Masa molecular", "Suma de las masas atómicas de una molécula, en u."], ["Masa molar", "Masa de un mol, en g/mol; numéricamente igual a la masa molecular."], ["Número de Avogadro", "6,022 × 10²³ partículas por mol."], ["Composición porcentual", "Porcentaje en masa de cada elemento en un compuesto."]],
      k:["Para la masa atómica promedio: multiplica la masa de cada isótopo por su abundancia (en fracción) y suma.", "Para la masa molecular: multiplica la masa atómica de cada elemento por su subíndice y suma todo.", "Para la composición porcentual: masa del elemento en la fórmula ÷ masa molecular × 100.", "Para convertir: moles = gramos ÷ masa molar; partículas = moles × 6,022 × 10²³."],
      e:"<p><b>1. Masa atómica del cloro:</b> ³⁵Cl (34,969 u, 75,76 %) y ³⁷Cl (36,966 u, 24,24 %). Masa = 34,969 × 0,7576 + 36,966 × 0,2424 = 26,49 + 8,96 = <b>35,45 u</b>.</p><p><b>2. Masas moleculares:</b></p><ul><li>H₂SO₄ = 2(1,008) + 32,06 + 4(16,00) = <b>98,08 g/mol</b>.</li><li>CaCO₃ = 40,08 + 12,01 + 3(16,00) = <b>100,09 g/mol</b>.</li><li>C₃H₈ = 3(12,01) + 8(1,008) = <b>44,09 g/mol</b>.</li><li>CO₂ = 12,01 + 2(16,00) = <b>44,01 g/mol</b>.</li></ul><p><b>3. Composición porcentual del Fe₂O₃ (hematita):</b> masa molar = 2(55,85) + 3(16,00) = 159,70 g/mol. % Fe = 111,70 ÷ 159,70 × 100 = <b>69,9 %</b>. Una tonelada de hematita pura contiene 699 kg de hierro.</p><p><b>4. Moles y moléculas:</b> 196 g de H₂SO₄ = 196 ÷ 98,08 = 2,0 mol = 2,0 × 6,022 × 10²³ = 1,20 × 10²⁴ moléculas.</p>",
      x:["Olvidar multiplicar por el subíndice (en H₂SO₄ hay 4 oxígenos).", "Usar el porcentaje de abundancia sin pasarlo a fracción (75,76 en vez de 0,7576).", "Confundir número atómico (protones) con masa atómica."],
      q:[mc("La masa molar del agua (H₂O) es aproximadamente:", ["10 g/mol", "16 g/mol", "18 g/mol", "20 g/mol"], 2, "2(1,008) + 16,00 = 18,02 g/mol."),
         mc("La referencia de la escala de masas atómicas es:", ["El hidrógeno 1", "El oxígeno 16", "El carbono 12", "El uranio 238"], 2, "1 u = 1/12 de la masa del ¹²C."),
         mc("¿Cuántos moles hay en 88 g de CO₂?", ["0,5", "1", "2", "4"], 2, "88 ÷ 44 = 2 mol."),
         mc("Un elemento tiene dos isótopos: 10 u (20 %) y 11 u (80 %). Su masa atómica es:", ["10,2 u", "10,5 u", "10,8 u", "11,0 u"], 2, "10 × 0,2 + 11 × 0,8 = 2 + 8,8 = 10,8 u (es el boro).")] } },

  { title:"7. Cantidades de reactivos y productos: reactivo limitante, pureza y rendimiento (indicador 1.3)",
    res:"<p>Con la ecuación balanceada: gramos → moles (÷ masa molar) → proporción de coeficientes → moles → gramos (× masa molar). El reactivo limitante se agota primero y define el producto máximo (rendimiento teórico). Rendimiento porcentual = real ÷ teórico × 100. Con materias primas impuras, se multiplica primero por la pureza.</p>",
    z:{ p:"<p>En la industria nunca se trabaja con reactivos puros ni se obtiene el 100 % teórico. Saber cuánto falta, cuánto sobra y cuánto se pierde es lo que convierte la química en costos y emisiones.</p>",
      s:"<p>La ecuación es una receta en moles. Si tienes los ingredientes en proporción distinta a la receta, uno se acaba antes (<b>limitante</b>) y del otro sobra (<b>en exceso</b>). Para encontrar el limitante, calcula cuánto producto daría cada reactivo por separado: el que da <b>menos</b> producto es el limitante.</p>",
      t:[["Reactivo limitante", "El que se consume por completo y limita el producto."], ["Reactivo en exceso", "El que sobra al terminar la reacción."], ["Rendimiento teórico", "Producto máximo calculado con el limitante."], ["Rendimiento real", "Producto que realmente se obtiene."], ["Rendimiento porcentual", "Real ÷ teórico × 100."], ["Pureza", "Fracción de la materia prima que es la sustancia que reacciona."]],
      k:["Balancea la ecuación.", "Corrige por pureza si corresponde (masa × pureza).", "Pasa cada reactivo a moles.", "Divide los moles de cada reactivo por su coeficiente: el menor cociente es el limitante.", "Con el limitante y la proporción de coeficientes, calcula los moles de producto.", "Pasa a masa y, si te dan el real, calcula el rendimiento."],
      e:"<p><b>1. Síntesis de amoníaco:</b> N₂ + 3 H₂ → 2 NH₃. Se mezclan 28,0 g de N₂ y 9,0 g de H₂.</p><ul><li>N₂: 28,0 ÷ 28,02 = 1,00 mol → 1,00 ÷ 1 = 1,00.</li><li>H₂: 9,0 ÷ 2,016 = 4,46 mol → 4,46 ÷ 3 = 1,49.</li><li>El menor cociente es el N₂: <b>limitante</b>. El H₂ está en exceso: se usan 3,00 mol y sobran 1,46 mol (2,9 g).</li><li>NH₃ teórico = 2 × 1,00 = 2,00 mol × 17,03 = <b>34,1 g</b>.</li><li>Si se obtienen 25,0 g: rendimiento = 25,0 ÷ 34,1 × 100 = <b>73,3 %</b>.</li></ul><p><b>2. Fabricación de cal (con pureza):</b> CaCO₃ → CaO + CO₂. Se calcinan 10 t de caliza con 90 % de CaCO₃.</p><ul><li>CaCO₃ puro = 10 × 0,90 = 9,0 t.</li><li>Por cada 100,09 t de CaCO₃ salen 56,08 t de CaO y 44,01 t de CO₂.</li><li>CaO = 9,0 × 56,08 ÷ 100,09 = <b>5,04 t</b>. CO₂ emitido = 9,0 × 44,01 ÷ 100,09 = <b>3,96 t</b> (emisión de proceso, distinta de la del combustible del horno).</li></ul>",
      x:["Elegir como limitante el reactivo con menos gramos (hay que comparar moles divididos por coeficiente).", "Olvidar la proporción de coeficientes (1 mol de N₂ da 2 mol de NH₃, no 1).", "No corregir por pureza.", "Calcular el rendimiento con el reactivo en exceso."],
      q:[mc("En 2 H₂ + O₂ → 2 H₂O, con 4 mol de H₂ y 3 mol de O₂, el limitante es:", ["H₂", "O₂", "Ninguno", "H₂O"], 0, "4 ÷ 2 = 2 y 3 ÷ 1 = 3: el menor es el H₂. Se forman 4 mol de H₂O y sobra 1 mol de O₂."),
         mc("Si el rendimiento teórico es 50 kg y se obtienen 42 kg, el rendimiento es:", ["42 %", "84 %", "92 %", "119 %"], 1, "42 ÷ 50 × 100 = 84 %."),
         mc("¿Cuánto CO₂ produce la combustión completa de 2 mol de propano (C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O)?", ["2 mol", "3 mol", "6 mol", "10 mol"], 2, "1 mol de propano da 3 mol de CO₂; 2 mol dan 6."),
         mc("Para 100 kg de un mineral con 60 % de pureza, la masa que reacciona es:", ["40 kg", "60 kg", "100 kg", "160 kg"], 1, "100 × 0,60 = 60 kg.")] } },

  { title:"8. Gases ideales y leyes de los gases (indicadores 2.1 y 2.2)",
    res:"<p>Gas ideal: partículas sin volumen propio ni fuerzas entre ellas, con choques elásticos; buena aproximación a baja presión y alta temperatura. Ecuación de estado PV = nRT (R = 0,08206 L·atm/(mol·K) = 8,314 J/(mol·K)). Boyle (T constante): P₁V₁ = P₂V₂. Charles (P constante): V₁/T₁ = V₂/T₂. Gay-Lussac (V constante): P₁/T₁ = P₂/T₂. Combinada: P₁V₁/T₁ = P₂V₂/T₂. Dalton: P total = suma de presiones parciales. Temperatura siempre en kelvin.</p>",
    z:{ p:"<p>Las emisiones son gases: para pasar de kilos de CO₂ a metros cúbicos, para entender por qué un contaminante se concentra en invierno o para convertir ppm a µg/m³ (unidad de las normas de calidad del aire), necesitas las leyes de los gases.</p>",
      s:"<p>En un gas las moléculas están muy separadas y se mueven al azar chocando con las paredes: esos choques son la <b>presión</b>. La <b>temperatura</b> mide qué tan rápido se mueven. Por eso:</p><ul><li>Si achicas el recipiente (menos volumen), chocan más seguido: <b>sube la presión</b> (Boyle).</li><li>Si calientas a presión constante, se mueven más rápido y empujan las paredes: <b>sube el volumen</b> (Charles).</li><li>Si calientas en un recipiente rígido: <b>sube la presión</b> (Gay-Lussac). Por eso un cilindro de gas al sol es peligroso.</li></ul>" +
        tb(["Ley", "Se mantiene constante", "Relación", "Fórmula"], [["Boyle", "T y n", "P inversamente proporcional a V", "P₁V₁ = P₂V₂"], ["Charles", "P y n", "V directamente proporcional a T", "V₁/T₁ = V₂/T₂"], ["Gay-Lussac", "V y n", "P directamente proporcional a T", "P₁/T₁ = P₂/T₂"], ["Avogadro", "P y T", "V proporcional a n", "V₁/n₁ = V₂/n₂"], ["Combinada", "n", "", "P₁V₁/T₁ = P₂V₂/T₂"], ["Gas ideal", "", "", "PV = nRT"]]) +
        "<p><b>Conversiones útiles:</b> K = °C + 273,15; 1 atm = 101,325 kPa = 760 mmHg; 1 m³ = 1.000 L. Volumen molar: 22,4 L/mol a 0 °C y 1 atm; 24,45 L/mol a 25 °C y 1 atm.</p><p><b>De ppm a µg/m³</b> (25 °C y 1 atm): µg/m³ = ppm × M × 1.000 ÷ 24,45, con M la masa molar en g/mol.</p>",
      t:[["P", "Presión (atm, kPa, mmHg)."], ["V", "Volumen (L o m³)."], ["n", "Cantidad de gas (mol)."], ["T", "Temperatura absoluta (K)."], ["R", "Constante de los gases: 0,08206 L·atm/(mol·K) u 8,314 J/(mol·K)."], ["Presión parcial", "Presión que ejercería un gas de la mezcla si estuviera solo: P<sub>i</sub> = fracción molar × P total."], ["ppm (en volumen)", "Partes por millón: moles de contaminante por millón de moles de aire."]],
      k:["Identifica qué variables cambian y cuáles quedan constantes: eso dice qué ley usar.", "Pasa la temperatura a kelvin.", "Usa las mismas unidades de presión y volumen a ambos lados.", "Despeja la incógnita y calcula.", "Revisa el sentido físico: si comprimes, la presión debe subir."],
      e:"<p><b>1. Boyle:</b> un compresor toma 10 L de aire a 1 atm y lo lleva a 2,5 atm a temperatura constante. V₂ = 1 × 10 ÷ 2,5 = <b>4 L</b>.</p><p><b>2. Charles:</b> un globo de 2,0 L a 27 °C (300 K) se calienta a 127 °C (400 K). V₂ = 2,0 × 400 ÷ 300 = <b>2,67 L</b>.</p><p><b>3. Gay-Lussac:</b> un neumático a 2,2 atm y 20 °C (293,15 K) se calienta en ruta a 50 °C (323,15 K). P₂ = 2,2 × 323,15 ÷ 293,15 = <b>2,43 atm</b>.</p><p><b>4. Gas ideal y emisiones:</b> ¿qué volumen ocupan los 2,75 kg de CO₂ que emite 1 kg de metano, a 25 °C y 1 atm? n = 2.750 ÷ 44 = 62,5 mol. V = nRT ÷ P = 62,5 × 0,08206 × 298,15 ÷ 1 = 1.529 L ≈ <b>1,53 m³</b>.</p><p><b>5. Conversión para normas:</b> 0,05 ppm de SO₂ (M = 64,07 g/mol) a 25 °C: 0,05 × 64,07 × 1.000 ÷ 24,45 = <b>131 µg/m³</b>.</p><p><b>6. Dalton:</b> el aire tiene 21 % de O₂. A nivel del mar (1 atm) la presión parcial de O₂ es 0,21 atm; en Calama (unos 2.260 m, cerca de 0,77 atm) es 0,21 × 0,77 = 0,16 atm: por eso cuesta más respirar y los motores pierden potencia en altura.</p>",
      x:["Usar °C en vez de K (con °C, a 0 °C la fórmula daría volumen cero).", "Mezclar unidades: R = 0,08206 exige atm y litros.", "Aplicar Boyle cuando cambia la temperatura.", "Olvidar pasar kg a g antes de dividir por la masa molar."],
      q:[mc("Si a temperatura constante la presión de un gas se duplica, su volumen:", ["Se duplica", "Se reduce a la mitad", "No cambia", "Se cuadruplica"], 1, "Boyle: P y V son inversamente proporcionales."),
         mc("¿En qué condición un gas real se comporta más parecido a uno ideal?", ["Alta presión y baja temperatura", "Baja presión y alta temperatura", "Cerca de licuarse", "En estado sólido"], 1, "Las moléculas están lejos y sus fuerzas son despreciables."),
         mc("Un gas ocupa 3 L a 300 K. A presión constante, a 600 K ocupará:", ["1,5 L", "3 L", "6 L", "9 L"], 2, "Charles: V₂ = 3 × 600 ÷ 300 = 6 L."),
         mc("¿Cuántos moles hay en 24,45 L de gas a 25 °C y 1 atm?", ["0,5", "1", "2", "24,45"], 1, "Es el volumen molar a esas condiciones."),
         mc("La ley que explica que un aerosol explote al calentarse es la de:", ["Boyle", "Charles", "Gay-Lussac", "Dalton"], 2, "A volumen constante, la presión sube con la temperatura.")] } },

  { title:"9. Atmósfera terrestre y cambio climático (indicador 2.3)",
    res:"<p>Aire seco: N₂ 78,08 %, O₂ 20,95 %, Ar 0,93 %, CO₂ cerca de 0,042 % (más de 420 ppm). Capas: troposfera (0 a 8 a 18 km, clima), estratosfera (hasta unos 50 km, capa de ozono), mesosfera (hasta unos 85 km), termosfera y exosfera. El efecto invernadero natural mantiene la Tierra a unos 15 °C; el aumento de GEI por actividad humana (combustibles fósiles, deforestación, ganadería, procesos industriales y residuos) lo intensifica y causa el cambio climático.</p>",
    z:{ p:"<p>El cambio climático ya cambia cómo operan las empresas en Chile: megasequía, menos agua para la minería y la agricultura, metas de carbono neutralidad y clientes que exigen huella de carbono.</p>",
      s:tb(["Capa", "Altura aproximada", "Temperatura", "Qué ocurre"], [
          ["Troposfera", "0 a 8 km (polos) y 18 km (ecuador)", "Baja con la altura (unos 6,5 °C por km)", "Contiene ~75 % de la masa del aire y casi todo el vapor de agua: clima y contaminación"],
          ["Estratosfera", "Hasta ~50 km", "Sube con la altura", "Capa de ozono (absorbe radiación UV); vuelan los aviones en su base"],
          ["Mesosfera", "Hasta ~85 km", "Baja (la más fría, cerca de −90 °C)", "Se queman los meteoros"],
          ["Termosfera", "Hasta ~600 km", "Muy alta", "Auroras; órbita de la Estación Espacial"],
          ["Exosfera", "Sobre ~600 km", "", "Transición al espacio"]]) +
        "<p><b>Efecto invernadero:</b> el Sol calienta la superficie, que emite radiación infrarroja; los gases de efecto invernadero (GEI) absorben parte de esa radiación y la reemiten hacia abajo. Sin ese efecto natural la temperatura media sería de unos −18 °C en vez de +15 °C. El problema es su <b>intensificación</b>: el CO₂ pasó de unas 280 ppm antes de la revolución industrial a más de 420 ppm hoy, y la temperatura media global ya subió alrededor de 1,1 °C (IPCC, AR6).</p>" +
        tb(["GEI", "Fuentes principales", "Potencial de calentamiento (PCG a 100 años, IPCC AR5)"], [["CO₂", "Combustibles fósiles, cemento, deforestación", "1"], ["CH₄ (metano)", "Ganadería, rellenos sanitarios, fugas de gas", "28"], ["N₂O (óxido nitroso)", "Fertilizantes, procesos químicos", "265"], ["Gases fluorados (HFC, SF₆)", "Refrigeración, equipos eléctricos", "Cientos a miles"], ["Vapor de agua", "Evaporación (responde a la temperatura)", "Se considera una retroalimentación"]]) +
        "<p>El AR6 actualiza estos valores (metano de origen fósil ≈ 29,8; N₂O ≈ 273): usa los que indique tu profesor o la herramienta oficial.</p><p><b>No confundas:</b> el <b>agujero de la capa de ozono</b> (estratosfera, causado por CFC, controlado por el Protocolo de Montreal) es un problema distinto del <b>cambio climático</b> (troposfera, causado por GEI, abordado por el Acuerdo de París). En Chile, la Ley Marco de Cambio Climático (Ley 21.455, 2022) fija la meta de carbono neutralidad a más tardar en 2050.</p>",
      t:[["GEI", "Gas de efecto invernadero: absorbe radiación infrarroja."], ["PCG (GWP)", "Potencial de calentamiento global: cuánto calienta 1 kg de un gas comparado con 1 kg de CO₂ en 100 años."], ["CO₂e", "CO₂ equivalente: masa del gas × PCG."], ["IPCC", "Panel Intergubernamental de Expertos sobre el Cambio Climático."], ["Forzamiento radiativo", "Desequilibrio de energía que provoca un cambio en la atmósfera (W/m²)."]],
      e:"<p><b>CO₂ equivalente:</b> un relleno sanitario emite al año 500 t de CH₄ y una planta 2 t de N₂O. Con PCG del AR5: 500 × 28 = 14.000 t CO₂e; 2 × 265 = 530 t CO₂e. Total = <b>14.530 t CO₂e</b>. Aunque se emitió 250 veces más metano que N₂O, ambos se comparan en la misma unidad.</p>",
      x:["Decir que el efecto invernadero es malo en sí: el natural es necesario; el problema es su intensificación.", "Mezclar el agujero de ozono con el calentamiento global.", "Ubicar la capa de ozono en la troposfera (está en la estratosfera).", "Olvidar multiplicar por el PCG al sumar gases distintos."],
      q:[mc("El gas más abundante en la atmósfera es:", ["O₂", "CO₂", "N₂", "Ar"], 2, "Nitrógeno, 78 %."),
         mc("La capa de ozono se encuentra en la:", ["Troposfera", "Estratosfera", "Mesosfera", "Termosfera"], 1, "Entre unos 15 y 35 km de altura."),
         mc("¿Cuál NO es un gas de efecto invernadero?", ["CH₄", "N₂O", "N₂", "CO₂"], 2, "El N₂ no absorbe radiación infrarroja."),
         mc("10 t de CH₄ (PCG = 28) equivalen a:", ["10 t CO₂e", "28 t CO₂e", "280 t CO₂e", "2.800 t CO₂e"], 2, "10 × 28 = 280."),
         mc("En la troposfera, al subir, la temperatura:", ["Aumenta", "Disminuye", "No cambia", "Se duplica"], 1, "Unos 6,5 °C menos por cada kilómetro.")] } },

  { title:"10. Contaminantes atmosféricos, métodos de control y normativa chilena (indicador 2.4)",
    res:"<p>Contaminantes primarios (emitidos directamente: MP, SO₂, NOx, CO, COV, plomo) y secundarios (se forman en la atmósfera: ozono troposférico, parte del MP2,5, lluvia ácida). Control de partículas: cámaras de sedimentación, ciclones, filtros de mangas, precipitadores electrostáticos y lavadores húmedos. Control de gases: desulfurización con caliza, reducción catalítica selectiva de NOx, convertidor catalítico, adsorción y oxidación térmica de COV. Normativa: Ley 19.300, normas primarias y secundarias de calidad, normas de emisión, declaración de zona latente o saturada y planes de prevención y descontaminación atmosférica (PPDA).</p>",
    z:{ p:"<p>Como ingeniero vas a elegir equipos de abatimiento, calcular si una chimenea cumple la norma y planificar la operación en episodios críticos. Y la prueba te pedirá distinguir contaminantes, equipos y normas.</p>",
      s:tb(["Contaminante", "Origen típico", "Efecto principal"], [
          ["MP10 y MP2,5 (material particulado)", "Combustión de leña, diésel, polvo, fundiciones", "Enfermedades respiratorias y cardiovasculares; el MP2,5 llega a los alvéolos"],
          ["SO₂ (dióxido de azufre)", "Fundiciones de cobre, carbón, combustibles con azufre", "Irritación respiratoria; lluvia ácida"],
          ["NOx (óxidos de nitrógeno)", "Motores y calderas a alta temperatura", "Precursor de ozono y MP2,5; lluvia ácida"],
          ["CO (monóxido de carbono)", "Combustión incompleta", "Tóxico: impide el transporte de oxígeno en la sangre"],
          ["O₃ troposférico (ozono)", "Secundario: NOx + COV + luz solar", "Irritación pulmonar; daña cultivos (esmog fotoquímico)"],
          ["COV (compuestos orgánicos volátiles)", "Solventes, pinturas, combustibles", "Precursor de ozono; algunos cancerígenos (benceno)"],
          ["Plomo", "Antes la gasolina con plomo; fundiciones", "Daño neurológico"]]) +
        "<p><b>Fuentes:</b> fijas (chimeneas industriales), móviles (vehículos) y areales o difusas (calefacción a leña, polvo de caminos).</p>" +
        tb(["Equipo de control", "Para qué", "Principio", "Eficiencia típica"], [
          ["Cámara de sedimentación", "Partículas gruesas", "Gravedad", "Baja (partículas > 50 µm)"],
          ["Ciclón", "Partículas medianas", "Fuerza centrífuga", "70 a 90 % (> 10 µm); baja en MP2,5"],
          ["Filtro de mangas", "Partículas finas", "Filtración en tela", "Sobre 99 %"],
          ["Precipitador electrostático", "Partículas finas, grandes caudales", "Carga eléctrica y placas colectoras", "Sobre 99 %"],
          ["Lavador húmedo (scrubber)", "Partículas y gases solubles (SO₂)", "Contacto con líquido", "90 a 99 %"],
          ["Desulfurización con caliza", "SO₂", "SO₂ + CaCO₃ + ½ O₂ → CaSO₄ + CO₂ (yeso)", "90 a 98 %"],
          ["Reducción catalítica selectiva (SCR)", "NOx", "Amoníaco o urea + catalizador → N₂ + H₂O", "80 a 95 %"],
          ["Convertidor catalítico de tres vías", "CO, HC y NOx de vehículos", "Oxidación y reducción en catalizador", "Sobre 90 %"],
          ["Carbón activado / oxidación térmica", "COV", "Adsorción / combustión", "95 a 99 %"]]) +
        "<p><b>Antes que el equipo, la prevención:</b> cambiar a combustibles más limpios (gas en vez de carbón o leña), mejorar la combustión, recambiar calefactores, capturar gases en fundiciones para fabricar ácido sulfúrico.</p>" +
        "<p><b>Normativa chilena</b> (verifica en la BCN y el MMA las versiones vigentes antes de la prueba):</p><ul><li><b>Ley 19.300</b> de Bases Generales del Medio Ambiente: crea los instrumentos de gestión (SEIA, normas, planes).</li><li><b>Norma primaria de calidad:</b> protege la salud de las personas (ej. MP2,5: 50 µg/m³ en 24 horas y 20 µg/m³ anual, DS 12/2011 del MMA; verificar).</li><li><b>Norma secundaria de calidad:</b> protege recursos naturales (suelos, vegetación, agua).</li><li><b>Norma de emisión:</b> límite a lo que sale de una fuente (ej. centrales termoeléctricas DS 13/2011; fundiciones de cobre DS 28/2013; verificar).</li><li><b>Zona latente:</b> la concentración está entre el 80 % y el 100 % de la norma; <b>zona saturada:</b> la supera. Se dicta un <b>PPDA</b> (ej. Región Metropolitana, Temuco y Padre Las Casas, Coyhaique).</li><li><b>Episodios críticos:</b> alerta, preemergencia y emergencia ambiental, con restricciones a fuentes y vehículos.</li><li><b>Impuesto verde</b> (Ley 20.780) a fuentes fijas por emisiones de CO₂, MP, NOx y SO₂.</li></ul>",
      t:[["Contaminante primario", "Se emite tal cual desde la fuente."], ["Contaminante secundario", "Se forma en la atmósfera por reacciones entre primarios."], ["Norma primaria", "Límite de concentración en el aire para proteger la salud."], ["Norma de emisión", "Límite de lo que sale por una chimenea o tubo de escape."], ["PPDA", "Plan de prevención y descontaminación atmosférica."], ["Eficiencia de remoción", "η = (entrada − salida) ÷ entrada × 100."]],
      k:["Identifica el contaminante y su tamaño o naturaleza (partícula o gas).", "Elige el equipo según tamaño de partícula, caudal y eficiencia exigida.", "Calcula la emisión de salida con la eficiencia.", "Compara con la norma de emisión.", "Si no cumple, combina equipos en serie o cambia el combustible o proceso."],
      e:"<p><b>Equipos en serie:</b> una caldera emite 500 kg/h de partículas. Se instala un ciclón (80 %) seguido de un filtro de mangas (99 %).</p><ul><li>Sale del ciclón: 500 × (1 − 0,80) = 100 kg/h.</li><li>Sale del filtro: 100 × (1 − 0,99) = <b>1 kg/h</b>.</li><li>Eficiencia global = 1 − (0,20 × 0,01) = <b>99,8 %</b>.</li></ul><p><b>Desulfurización:</b> una fundición emite 10 t/día de SO₂. ¿Cuánta caliza (CaCO₃) necesita el lavador? SO₂ + CaCO₃ + ½ O₂ → CaSO₄ + CO₂. Moles de SO₂ = 10.000.000 ÷ 64,07 = 156.080 mol. Caliza = 156.080 × 100,09 g = 15,6 t/día (más un exceso en la práctica). Se forman 156.080 × 136,14 g = 21,2 t/día de yeso (CaSO₄).</p>",
      x:["Decir que el ciclón sirve para MP2,5: su eficiencia en partículas finas es baja.", "Confundir norma de calidad (aire que respiramos) con norma de emisión (chimenea).", "Pensar que el ozono troposférico se emite directamente: es secundario.", "Sumar eficiencias en serie (80 % + 99 %): se multiplican las fracciones que pasan."],
      q:[mc("¿Cuál es un contaminante secundario?", ["CO", "SO₂", "Ozono troposférico", "Plomo"], 2, "Se forma por reacción de NOx y COV con luz solar."),
         mc("Para retener partículas finas con más de 99 % de eficiencia se usa:", ["Cámara de sedimentación", "Ciclón", "Filtro de mangas", "Convertidor catalítico"], 2, "También sirve un precipitador electrostático."),
         mc("Una zona donde la concentración supera la norma primaria se declara:", ["Zona latente", "Zona saturada", "Zona de sacrificio", "Zona franca"], 1, "Latente es entre 80 % y 100 % de la norma."),
         mc("La norma que limita lo que sale por la chimenea de una termoeléctrica es una norma:", ["Primaria de calidad", "Secundaria de calidad", "De emisión", "ISO 14001"], 2, "Las normas de emisión regulan fuentes."),
         mc("La ley que establece los instrumentos de gestión ambiental en Chile es la:", ["Ley 16.744", "Ley 19.300", "Ley 20.920", "Ley 21.455"], 1, "Ley 19.300; la 20.920 es la Ley REP y la 21.455 la de cambio climático.")] } },

  { title:"11. Energía en las reacciones químicas: entalpía y calor (indicador 3.1)",
    res:"<p>ΔH < 0: reacción exotérmica (libera calor, como la combustión). ΔH > 0: endotérmica (absorbe calor, como la calcinación de caliza). ΔH°reacción = Σ n ΔH°f(productos) − Σ n ΔH°f(reactivos). Ley de Hess: si una reacción es suma de otras, su ΔH es la suma de los ΔH. Calor sensible: q = m · c · ΔT (agua: c = 4,184 kJ/(kg·°C)).</p>",
    z:{ p:"<p>Toda caldera, horno o proceso químico consume o libera energía. Calcularla te dice cuánto combustible necesitas, cuánto cuesta y cuánto CO₂ emites.</p>",
      s:"<p>La <b>entalpía (H)</b> es el contenido de energía de una sustancia a presión constante. Lo que importa es su cambio, <b>ΔH</b>, entre productos y reactivos. En la combustión los productos (CO₂ y H₂O) tienen menos energía que los reactivos: la diferencia sale como calor.</p><p>La <b>entalpía estándar de formación (ΔH°f)</b> es la energía para formar 1 mol de un compuesto desde sus elementos en estado estándar (25 °C, 1 atm). Para los elementos puros (O₂, N₂, C grafito) vale 0.</p>" +
        tb(["Sustancia", "ΔH°f (kJ/mol)", "Sustancia", "ΔH°f (kJ/mol)"], [["CO₂ (g)", "−393,5", "CH₄ (g)", "−74,8"], ["H₂O (l)", "−285,8", "C₃H₈ (g)", "−103,8"], ["H₂O (g)", "−241,8", "CaCO₃ (s)", "−1.206,9"], ["CO (g)", "−110,5", "CaO (s)", "−635,1"]]),
      t:[["Sistema y entorno", "El sistema es lo que estudias (la reacción); el entorno es todo lo demás."], ["Exotérmica", "Libera calor al entorno; ΔH negativo."], ["Endotérmica", "Absorbe calor del entorno; ΔH positivo."], ["Calor específico (c)", "Energía para subir 1 °C la temperatura de 1 kg de sustancia."], ["Poder calorífico", "Energía liberada al quemar 1 kg (o 1 m³) de combustible."], ["Calorimetría", "Medición del calor de una reacción por el cambio de temperatura de una masa conocida."]],
      k:["Escribe la ecuación balanceada con estados (s, l, g).", "Busca los ΔH°f en la tabla.", "Suma productos (× coeficiente) y resta reactivos (× coeficiente).", "Interpreta el signo: negativo libera, positivo absorbe.", "Escala a la cantidad real: kJ/mol × moles.", "Si hay que calentar algo, usa q = m · c · ΔT y divide por la eficiencia del equipo."],
      e:"<p><b>1. Calor de combustión del metano:</b> CH₄ + 2 O₂ → CO₂ + 2 H₂O(l).</p><p>ΔH = [−393,5 + 2(−285,8)] − [−74,8 + 2(0)] = −965,1 + 74,8 = <b>−890,3 kJ/mol</b> (exotérmica).</p><p>Por kilo: 1.000 ÷ 16 = 62,5 mol × 890,3 = 55.644 kJ ≈ <b>55,6 MJ/kg</b>.</p><p><b>2. Aplicación:</b> un hotel calienta 1.000 L de agua de 15 °C a 60 °C con una caldera a gas de 85 % de eficiencia.</p><ul><li>q = 1.000 kg × 4,184 × 45 = 188.280 kJ = 188,3 MJ.</li><li>Gas necesario = 188,3 ÷ (55,6 × 0,85) = <b>3,98 kg de metano</b>.</li><li>CO₂ emitido = 3,98 × 2,75 = <b>10,9 kg</b> por cada 1.000 L de agua caliente.</li></ul><p><b>3. Reacción endotérmica:</b> CaCO₃ → CaO + CO₂. ΔH = (−635,1 − 393,5) − (−1.206,9) = <b>+178,3 kJ/mol</b>: hay que entregar calor (por eso los hornos de cal queman combustible).</p><p><b>4. Ley de Hess:</b> ¿ΔH de C + ½ O₂ → CO? Se conocen C + O₂ → CO₂ (−393,5) y CO + ½ O₂ → CO₂ (−283,0). Se suma la primera y la segunda invertida (+283,0): ΔH = −393,5 + 283,0 = <b>−110,5 kJ/mol</b>.</p>",
      x:["Restar al revés (reactivos − productos).", "Olvidar multiplicar por los coeficientes.", "Confundir H₂O líquida con gaseosa (cambia el ΔH°f).", "Al invertir una reacción en Hess, no cambiarle el signo al ΔH.", "Olvidar la eficiencia del equipo al calcular el combustible."],
      q:[mc("Una reacción con ΔH = −250 kJ es:", ["Endotérmica", "Exotérmica", "Isotérmica", "No ocurre"], 1, "ΔH negativo: libera calor."),
         mc("¿Cuánta energía se necesita para calentar 2 kg de agua de 20 °C a 70 °C (c = 4,184 kJ/kg·°C)?", ["167 kJ", "418 kJ", "586 kJ", "837 kJ"], 1, "2 × 4,184 × 50 = 418,4 kJ."),
         mc("La entalpía de formación del O₂ (g) en estado estándar es:", ["−393,5 kJ/mol", "0", "+100 kJ/mol", "Depende de la cantidad"], 1, "Por definición, los elementos en su estado estándar valen 0."),
         mc("Si A → B tiene ΔH = +50 kJ, entonces B → A tiene:", ["+50 kJ", "−50 kJ", "0", "+100 kJ"], 1, "Al invertir la reacción, el signo cambia."),
         mc("La calcinación de la caliza es:", ["Exotérmica", "Endotérmica", "Una combustión", "Una neutralización"], 1, "ΔH = +178 kJ/mol: absorbe calor.")] } },

  { title:"12. Fuentes de energía comparadas desde la termodinámica (indicador 3.2)",
    res:"<p>Primera ley: la energía no se crea ni se destruye, se transforma (ΔU = Q − W). Segunda ley: ninguna máquina térmica convierte todo el calor en trabajo; el máximo es la eficiencia de Carnot η = 1 − T<sub>fría</sub>/T<sub>caliente</sub> (en K). Se comparan fuentes fósiles, nuclear, solar, eólica, hidroeléctrica, biomasa y geotérmica por su conversión de energía, eficiencia, emisiones de ciclo de vida, variabilidad y costo.</p>",
    z:{ p:"<p>Elegir la fuente de energía de una planta (o evaluar un contrato eléctrico) exige comparar eficiencia, emisiones, disponibilidad y costo. La termodinámica explica por qué una termoeléctrica pierde más de la mitad de la energía del combustible.</p>",
      s:"<p><b>Primera ley:</b> la energía del combustible se convierte en electricidad y en calor perdido; la suma siempre es 100 %. <b>Eficiencia</b> = energía útil ÷ energía entregada.</p><p><b>Segunda ley:</b> para convertir calor en trabajo necesitas una fuente caliente y una fría, y siempre se pierde calor hacia la fría. Mientras mayor la diferencia de temperaturas, mayor la eficiencia máxima posible (Carnot). Por eso el ciclo combinado (turbina a gas + turbina a vapor) supera a una central a carbón: aprovecha temperaturas más altas y reutiliza el calor de escape.</p>" +
        tb(["Fuente", "Conversión", "Eficiencia típica", "Emisiones de ciclo de vida (g CO₂e/kWh, medianas IPCC)", "Ventajas / desventajas"], [
          ["Carbón", "Química → térmica → mecánica → eléctrica", "33 a 40 %", "≈ 820", "Firme y barata / mayor emisor de CO₂, SO₂ y MP"],
          ["Gas natural (ciclo combinado)", "Química → térmica → eléctrica (dos ciclos)", "50 a 60 %", "≈ 490", "Flexible, menos emisiones que el carbón / fósil, importado en Chile"],
          ["Nuclear", "Nuclear (fisión) → térmica → eléctrica", "≈ 33 %", "≈ 12", "Sin CO₂ en operación, firme / residuos radiactivos, alto costo, riesgo; Chile no tiene centrales"],
          ["Solar fotovoltaica", "Radiación → eléctrica (efecto fotovoltaico)", "18 a 23 % (panel)", "≈ 41 a 48", "Mejor recurso del mundo en el norte de Chile / solo de día, requiere almacenamiento"],
          ["Solar de concentración", "Radiación → térmica → eléctrica", "15 a 20 % anual", "≈ 27", "Almacena en sales fundidas (Cerro Dominador) / alto costo"],
          ["Eólica", "Cinética del viento → mecánica → eléctrica", "35 a 45 % (límite de Betz: 59,3 %)", "≈ 11 a 12", "Baja emisión / variable, impacto en aves y paisaje"],
          ["Hidroeléctrica", "Potencial del agua → mecánica → eléctrica", "85 a 90 %", "≈ 24", "La más eficiente, firme si hay embalse / sequía, impacto en ríos y comunidades"],
          ["Biomasa", "Química (fotosíntesis) → térmica → eléctrica", "20 a 35 %", "≈ 230", "Usa residuos forestales; el CO₂ biogénico se reabsorbe / MP local, uso de suelo"],
          ["Geotérmica", "Calor interno de la Tierra → eléctrica", "10 a 20 %", "≈ 38", "Firme (Cerro Pabellón) / exploración cara"]]) +
        "<p>Los valores son rangos de referencia para comparar (IPCC 2014 para emisiones). En Chile, las renovables ya generan más de la mitad de la electricidad: revisa el dato vigente en el Coordinador Eléctrico Nacional o la CNE (verificar).</p>",
      t:[["Primera ley", "Conservación de la energía: ΔU = Q − W."], ["Segunda ley", "El calor no se convierte completamente en trabajo; la entropía del universo aumenta."], ["Eficiencia de Carnot", "Máximo teórico de una máquina térmica: 1 − T<sub>f</sub>/T<sub>c</sub>."], ["Energía renovable", "Proviene de fuentes que se regeneran (sol, viento, agua, biomasa)."], ["Factor de planta", "Energía generada en el año ÷ energía si operara a plena potencia todo el año."], ["Límite de Betz", "Máximo de energía del viento que puede captar una turbina: 59,3 %."]],
      k:["Identifica la cadena de conversión de la fuente.", "Calcula la energía útil con la eficiencia (útil = entregada × η).", "Si es térmica, compara con el límite de Carnot.", "Compara emisiones por kWh y variabilidad (factor de planta).", "Concluye con criterio técnico, ambiental y económico."],
      e:"<p><b>1. Carnot:</b> una central a vapor trabaja entre 550 °C (823 K) y 30 °C (303 K). η máx = 1 − 303 ÷ 823 = <b>63,2 %</b>. La real es cercana a 40 %: las pérdidas por fricción y transferencia de calor la alejan del ideal.</p><p><b>2. Primera ley en una termoeléctrica:</b> 1.000 MJ de carbón con η = 38 % dan 380 MJ de electricidad (105,6 kWh) y 620 MJ de calor perdido al agua de enfriamiento.</p><p><b>3. Hidroeléctrica:</b> P = ρ · g · Q · H · η = 1.000 × 9,81 × 20 m³/s × 100 m × 0,90 = <b>17,7 MW</b>.</p><p><b>4. Eólica:</b> P = ½ · ρ · A · v³ · C<sub>p</sub>. Rotor de 100 m de diámetro (A = 7.854 m²), viento de 10 m/s, ρ = 1,225 kg/m³, C<sub>p</sub> = 0,40: P = 0,5 × 1,225 × 7.854 × 1.000 × 0,40 = <b>1,92 MW</b>. Si el viento baja a 5 m/s, la potencia cae a 1/8 (por el v³).</p><p><b>5. Solar:</b> un panel de 2 m² con 20 % de eficiencia bajo 1.000 W/m² entrega 1.000 × 2 × 0,20 = <b>400 W</b>.</p><p><b>6. Comparar emisiones:</b> 1.000 MWh producidos con carbón emiten unas 820 t CO₂e; con eólica, unas 12 t.</p>",
      x:["Usar °C en la fórmula de Carnot (debe ser en K).", "Creer que una central puede tener 100 % de eficiencia: lo impide la segunda ley.", "Decir que la nuclear emite mucho CO₂ (en operación no emite; sus problemas son otros).", "Olvidar que la potencia eólica depende del cubo de la velocidad."],
      q:[mc("La eficiencia de Carnot entre 600 K y 300 K es:", ["25 %", "50 %", "75 %", "100 %"], 1, "1 − 300 ÷ 600 = 0,5."),
         mc("¿Qué ley impide que una máquina térmica tenga 100 % de eficiencia?", ["Ley cero", "Primera ley", "Segunda ley", "Ley de Boyle"], 2, "Siempre se cede calor a la fuente fría."),
         mc("¿Cuál fuente tiene la mayor eficiencia de conversión?", ["Carbón", "Solar fotovoltaica", "Hidroeléctrica", "Biomasa"], 2, "Sobre 85 %."),
         mc("Si la velocidad del viento se duplica, la potencia de una turbina:", ["Se duplica", "Se cuadruplica", "Se multiplica por 8", "No cambia"], 2, "Depende de v³: 2³ = 8."),
         mc("¿Qué fuente usa la fisión de átomos de uranio?", ["Geotérmica", "Nuclear", "Solar", "Biomasa"], 1, "La fisión libera calor que mueve una turbina a vapor.")] } },

  { title:"13. Huella de carbono de procesos industriales y químicos (indicador 3.3)",
    res:"<p>Huella de carbono: total de GEI emitidos por una organización, producto o proceso, expresado en t CO₂e. Emisión = dato de actividad × factor de emisión × PCG. Alcance 1: emisiones directas (combustibles propios, procesos, fugas). Alcance 2: electricidad comprada. Alcance 3: otras indirectas (transporte de terceros, insumos, viajes, residuos). Estándares: GHG Protocol, ISO 14064-1 (organizaciones), ISO 14067 (productos). En Chile: programa HuellaChile del Ministerio del Medio Ambiente.</p>",
    z:{ p:"<p>Las empresas que exportan, las que licitan con grandes mineras y las afectas al impuesto verde ya deben calcular y reducir su huella. Es una de las tareas típicas de un ingeniero industrial joven.</p>",
      s:"<p>La huella se calcula como un inventario: listas todas las actividades que emiten, multiplicas cada una por su factor de emisión y sumas. Si hay gases distintos del CO₂, los pasas a CO₂e con su PCG.</p>" +
        tb(["Alcance", "Qué incluye", "Ejemplos"], [["1 (directas)", "Fuentes propias o controladas", "Diésel de camiones propios, gas de calderas, CO₂ de calcinación, fugas de refrigerante"], ["2 (indirectas por energía)", "Electricidad (y vapor) comprados", "Consumo eléctrico de la planta"], ["3 (otras indirectas)", "Cadena de valor", "Transporte contratado, materias primas, viajes, residuos, uso del producto"]]) +
        tb(["Factor de emisión de referencia", "Valor"], [["Diésel", "≈ 2,68 kg CO₂ por litro"], ["Gasolina", "≈ 2,3 kg CO₂ por litro"], ["Gas natural", "≈ 1,9 kg CO₂ por m³"], ["Electricidad del Sistema Eléctrico Nacional (HuellaChile 2023)", "0,2421 kg CO₂e por kWh (se actualiza cada año: verificar)"], ["Calcinación de CaCO₃", "0,44 t CO₂ por t de CaCO₃ (estequiometría: 44,01 ÷ 100,09)"]]) +
        "<p>Para reportes oficiales usa siempre los factores vigentes de HuellaChile o del IPCC; estos valores sirven para estudiar.</p>",
      t:[["Dato de actividad", "Cantidad consumida o producida (litros, kWh, toneladas, km)."], ["Factor de emisión", "kg de GEI por unidad de actividad."], ["Intensidad de emisiones", "Huella por unidad de producto (kg CO₂e por tonelada producida)."], ["Compensación", "Financiar reducciones fuera de la empresa (bonos de carbono) para neutralizar emisiones que no se pudieron evitar."], ["Carbono neutralidad", "Emisiones netas iguales a cero después de reducir y compensar."]],
      k:["Define el límite (organización, planta o producto) y el año.", "Lista las fuentes y clasifícalas en alcance 1, 2 o 3.", "Reúne los datos de actividad (facturas, medidores).", "Multiplica por el factor de emisión (y el PCG si no es CO₂).", "Suma por alcance y en total (t CO₂e).", "Calcula la intensidad por unidad de producto.", "Propón medidas de reducción y estima su efecto."],
      e:"<p><b>Huella anual de una planta de cal</b> que produce 50.000 t de CaO.</p>" +
        tb(["Fuente", "Alcance", "Cálculo", "t CO₂e"], [
          ["Calcinación (proceso)", "1", "89.250 t CaCO₃ × 0,44", "39.270"],
          ["Gas natural del horno", "1", "12.000.000 m³ × 1,9 kg ÷ 1.000", "22.800"],
          ["Diésel de cargadores", "1", "150.000 L × 2,68 kg ÷ 1.000", "402"],
          ["Electricidad", "2", "8.000.000 kWh × 0,2421 kg ÷ 1.000", "1.937"],
          ["Transporte contratado", "3", "2.000.000 t·km × 0,1 kg ÷ 1.000 (factor supuesto)", "200"],
          ["<b>Total</b>", "", "", "<b>64.609</b>"]]) +
        "<p>Para 50.000 t de CaO se necesitan 50.000 × 100,09 ÷ 56,08 = 89.237 t de CaCO₃ puro (redondeado a 89.250). Intensidad = 64.609 ÷ 50.000 = <b>1,29 t CO₂e por t de cal</b>. El 61 % viene de la propia química (calcinación): no se elimina cambiando de combustible, sino con captura de carbono o materias primas alternativas.</p><p><b>Medida de reducción:</b> contratar electricidad 100 % renovable con certificado elimina casi todo el alcance 2 (1.937 t, el 3 %); mejorar 10 % la eficiencia del horno ahorra 2.280 t.</p><p><b>Otro proceso:</b> una fuga anual de 50 kg de refrigerante R-134a (PCG ≈ 1.300, AR5) = 50 × 1.300 ÷ 1.000 = <b>65 t CO₂e</b>, lo mismo que quemar unos 24.000 L de diésel.</p>",
      x:["Poner la electricidad en el alcance 1 (es alcance 2).", "Olvidar las emisiones de proceso (calcinación, reacciones químicas): no vienen del combustible.", "Sumar kg con t o kWh con MWh.", "Usar factores de electricidad de otro país o de otro año.", "Sumar gases distintos sin pasarlos a CO₂e."],
      u:"<p>Calcula tus propios casos con la herramienta del programa: " + goBtn("huella") + "</p>",
      q:[mc("El consumo de electricidad comprada a la red pertenece al:", ["Alcance 1", "Alcance 2", "Alcance 3", "No se contabiliza"], 1, "Emisiones indirectas por energía comprada."),
         mc("Una empresa consume 100.000 kWh al año. Con 0,2421 kg CO₂e/kWh, su alcance 2 es:", ["2,42 t", "24,2 t", "242 t", "2.421 t"], 1, "100.000 × 0,2421 = 24.210 kg = 24,2 t."),
         mc("El diésel de los camiones propios es alcance:", ["1", "2", "3", "Ninguno"], 0, "Combustión directa en fuentes controladas."),
         mc("Una flota consume 10.000 L de diésel (2,68 kg CO₂/L). Emite:", ["2,68 t", "26,8 t", "268 t", "2.680 t"], 1, "10.000 × 2,68 = 26.800 kg."),
         mc("¿Qué norma ISO trata la huella de carbono de productos?", ["ISO 9001", "ISO 14001", "ISO 14067", "ISO 45001"], 2, "La ISO 14064-1 es para organizaciones.")] } },

  { title:"14. Repaso para la prueba: mapa de indicadores y preguntas tipo",
    res:"<p>Mapa de indicadores de logro con la unidad donde se estudia cada uno, y preguntas integradas con su pauta.</p>",
    z:{ s:tb(["Indicador", "Qué te piden", "Dónde estudiarlo"], [
          ["1.1", "Balancear ecuaciones (masa y carga)", "Unidades 1 y 2"],
          ["1.2", "Pesos atómicos y moleculares", "Unidad 3"],
          ["1.3", "Cantidades de reactivos y productos", "Unidades 1 y 4"],
          ["2.1", "Características de los gases ideales en problemas ambientales", "Unidad 5"],
          ["2.2", "Presión, volumen y temperatura (leyes de los gases)", "Unidad 5"],
          ["2.3", "Atmósfera y cambio climático", "Unidad 6"],
          ["2.4", "Contaminantes, control y normativa", "Unidades 7 y 8"],
          ["3.1", "Intercambios de energía en reacciones", "Unidad 9"],
          ["3.2", "Fuentes de energía y termodinámica", "Unidad 10"],
          ["3.3", "Huella de carbono", "Unidades 8 y 11"]]) +
        "<p><b>Cadena que une todo el ramo:</b> ecuación balanceada → masas molares → moles → masa de CO₂ (estequiometría) → volumen del gas (PV = nRT) → energía liberada (ΔH) → huella de carbono (t CO₂e) → norma o meta que hay que cumplir.</p>",
      e:"<p><b>Problema integrado:</b> una caldera quema 100 kg de propano al día (C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O; ΔH = −2.220 kJ/mol).</p><ul><li>Moles de propano = 100.000 ÷ 44,09 = 2.268 mol.</li><li>CO₂ = 3 × 2.268 = 6.804 mol × 44,01 = 299,4 kg ≈ <b>0,30 t CO₂ al día</b> (≈ 3,0 kg de CO₂ por kg de propano).</li><li>Volumen de CO₂ a 25 °C y 1 atm = 6.804 × 24,45 L = 166.360 L ≈ <b>166 m³</b>.</li><li>Energía liberada = 2.268 × 2.220 = 5.035.000 kJ ≈ <b>5.035 MJ</b> al día.</li><li>O₂ necesario = 5 × 2.268 = 11.340 mol × 32,00 = <b>363 kg</b>; como el aire tiene 21 % de O₂, el volumen de aire teórico es 11.340 ÷ 0,21 × 24,45 L ≈ 1.320 m³.</li><li>Huella anual (alcance 1, 365 días) ≈ 0,30 × 365 = <b>109 t CO₂</b>.</li></ul>",
      q:[mc("Al quemar 1 mol de C₃H₈ se forman:", ["1 mol de CO₂", "3 mol de CO₂ y 4 mol de H₂O", "5 mol de CO₂", "3 mol de CO₂ y 8 mol de H₂O"], 1, "C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O."),
         mc("Un gas en un estanque rígido pasa de 300 K a 360 K. Si la presión era 5 atm, ahora es:", ["4,2 atm", "5 atm", "6 atm", "7,2 atm"], 2, "5 × 360 ÷ 300 = 6 atm."),
         mc("¿Qué medida reduce el alcance 2 de una empresa?", ["Cambiar los camiones a eléctricos cargados en la red", "Contratar electricidad renovable", "Reducir los viajes en avión", "Capturar el CO₂ de la caldera"], 1, "El alcance 2 es la electricidad comprada."),
         mc("Para controlar SO₂ de una fundición se usa:", ["Ciclón", "Desulfurización con caliza o planta de ácido", "Filtro de mangas", "Convertidor catalítico de tres vías"], 1, "El SO₂ es un gas: se absorbe o se convierte en ácido sulfúrico."),
         mc("¿Cuál par está bien relacionado?", ["Boyle: V y T a P constante", "Charles: P y V a T constante", "Gay-Lussac: P y T a V constante", "Dalton: V y n a P constante"], 2, "Gay-Lussac relaciona presión y temperatura con volumen constante.")] } }
  ]);
  /* Orden de estudio = orden de los indicadores de logro: reordena unidades (y sus explicaciones y figuras) y renumera */
  const order = (id, ix, tag) => { const c = COURSES.find(x => x.id === id); if (!c || c.u.length !== ix.length || c._ord) return; c._ord = 1;
    const u = c.u.slice(), z = (UZ[id] || []).slice(), x = (UX[id] || []).slice();
    c.u = ix.map((k, n) => [(n + 1) + ". " + u[k][0].replace(/^\d+\.\s*/, "") + (tag[k] ? " (" + tag[k] + ")" : ""), u[k][1]]);
    UZ[id] = ix.map(k => z[k]); if (UX[id]) UX[id] = ix.map(k => x[k]); };
  order("ramo-intro-optimizacion", [4, 5, 6, 0, 1, 2, 7, 3, 8], { 0:"indicadores 2.1 y 2.2", 1:"indicador 2.2", 2:"indicador 2.2", 3:"indicador 2.3" });
  order("ramo-quimica-ambiente", [0, 4, 5, 6, 7, 8, 9, 1, 10, 11, 12, 2, 3, 13], { 0:"indicadores 1.1 y 1.3", 1:"indicadores 2.4 y 3.3", 2:"complementaria", 3:"complementaria" });
})();
